import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/recipes.json').read_text());R=DATA['recipes'];N=DATA['notes'];P=DATA['pages']
def esc(s):return html.escape(str(s),quote=True)
def url(r):return f"/recipes/r/{r['id']}/"
def shell(title,body,recipe='',description='Книга рецептов из семейных сканов: ингредиенты, приготовление и рукописные заметки.',path=''):
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Книга рецептов</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#ffffff"><link rel="canonical" href="https://ilyamanik.ru/recipes/{path}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/recipes/style.css"><script defer src="/recipes/app.js"></script><link rel="icon" href="/recipes/favicon.svg" type="image/svg+xml"></head><body data-recipe="{esc(recipe)}"><a class="skip" href="#main">К содержанию</a><header class="masthead"><div class="brand-group"><a class="site-home" href="/">Илья Маник <span aria-hidden="true">/</span></a><a class="brand" href="/recipes/">Книга рецептов</a></div><nav aria-label="Основная навигация"><a href="/recipes/">Рецепты</a><a href="/recipes/notes/">Заметки</a><a href="/recipes/archive/">Архив</a><a href="/recipes/about/">О книге</a></nav></header>{body}<footer class="footer"><span><a href="/">Илья Маник</a> · 73 рецепта · 94 страницы</span><span><a href="/recipes/downloads/recipe-book.docx" download>Скачать книгу Word</a> · <a href="/recipes/about/">Об источниках</a></span></footer><noscript><p class="book-page">Все рецепты доступны без JavaScript. Для поиска, избранного и сохранения отметок включите JavaScript.</p></noscript></body></html>'''
def write(path,content):
 dest=ROOT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
def source_links(sources):
 return ' · '.join(f'<a href="/recipes/scans/{s["pdf"]}-{s["page"]:02}.jpg" target="_blank" rel="noopener">PDF {s["pdf"]}, с. {s["page"]}</a>' for s in sources)
def sources_panel(sources):
 figures=''.join(f'<figure><a href="/recipes/scans/{s["pdf"]}-{s["page"]:02}.jpg" target="_blank" rel="noopener"><img loading="lazy" src="/recipes/scans/{s["pdf"]}-{s["page"]:02}.jpg" alt="Исходный лист PDF {s["pdf"]}, страница {s["page"]}"></a><figcaption>PDF {s["pdf"]}, страница {s["page"]} · <a href="/recipes/scans/{s["pdf"]}-{s["page"]:02}.jpg" target="_blank" rel="noopener">Открыть крупно</a></figcaption></figure>' for s in sources)
 return f'<details class="source-details"><summary>Сверить с оригиналом · {len(sources)} стр.</summary><div class="source-grid">{figures}</div></details>'
categories=['Все рецепты']+list(dict.fromkeys(r['category'] for r in R))
catbuttons=''.join(f'<button class="category" data-category-filter="{esc(cat)}" aria-pressed="{str(i==0).lower()}"><span>{esc(cat)}</span><small>{len(R) if i==0 else sum(r["category"]==cat for r in R)}</small></button>' for i,cat in enumerate(categories))
cards=[]
for r in R:
 search=' '.join([r['title'],r['category']]+[i['name'] for i in r['ingredients']]+r['notes']).lower().replace('ё','е')
 preview=', '.join(i['name'].lower() for i in r['ingredients'][:4])
 cards.append(f'''<article class="recipe-card" data-id="{r['id']}" data-category="{esc(r['category'])}" data-kind="{r['kind']}" data-issues="{str(bool(r['issues'])).lower()}" data-search="{esc(search)}"><span class="card-number">{r['number']:02} / {esc(r['category'])}</span><h3><a href="{url(r)}">{esc(r['title'])}</a></h3><button class="star js-only" data-favorite="{r['id']}" data-title="{esc(r['title'])}" aria-pressed="false" aria-label="В избранное: {esc(r['title'])}">☆</button><p>{esc(preview)}</p><div class="card-meta"><span>{esc(r['yieldText'] or 'Выход не указан')}</span>{'<span class="tag">Фрагмент</span>' if r['kind']=='fragment' else ''}{'<span>Есть уточнения</span>' if r['issues'] else ''}</div></article>''')
body=f'''<div class="layout"><aside class="sidebar" aria-label="Разделы книги"><p class="eyebrow">Оглавление</p><details class="category-picker" open><summary>Разделы книги</summary><nav class="categories" aria-label="Категории">{catbuttons}</nav></details><p class="sidebar-note">Рукописные дополнения сохранены рядом с рецептами. Каждый лист можно открыть и рассмотреть.</p></aside><main id="main"><section class="hero"><div><p class="eyebrow">Личная коллекция / 73 рецепта</p><h1>Рецепты,<br>которые рядом.</h1><p>Завтраки, супы, домашняя выпечка и записи на полях. Найдите блюдо и откройте всё нужное для приготовления.</p></div><figure><img src="/recipes/scans/4-08.jpg" width="180" height="218" alt="Рукописная запись рецепта ленивых вареников"><figcaption>Ленивые вареники<br>из рукописной тетради</figcaption></figure></section><section class="search-tools js-only" aria-label="Поиск рецептов"><label for="search">Название блюда или ингредиент</label><div class="search-row"><input id="search" type="search" placeholder="Например, кабачок или шарлотка" autocomplete="off"><button class="clear-search" data-reset>Сбросить</button></div><div class="filter-line"><button id="favorites-filter" aria-pressed="false">Только избранное</button><select id="status-filter" aria-label="Тип записи"><option value="">Все записи</option><option value="fragment">Фрагменты рецептов</option><option value="issues">Есть уточнения</option></select></div></section><div class="results-heading"><h2 id="results-title">Все рецепты</h2><p id="results-count" role="status" aria-live="polite">Записей: {len(R)}</p></div><div class="recipe-grid">{''.join(cards)}</div><div id="empty" class="empty" hidden><h2>Рецептов не нашлось</h2><p>Попробуйте другой ингредиент или сбросьте фильтры. Избранное сохраняется только в этом браузере.</p><button data-reset>Показать все рецепты</button></div></main></div>'''
write('index.html',shell('Каталог',body))
for idx,r in enumerate(R):
 ingredients=''.join(f'<li class="ingredient"><label><input type="checkbox" aria-label="Отметить: {esc(i["name"])}"><span class="ingredient-text"><span>{esc(i["name"])}</span><span class="amount">{esc(i["amount"])}</span></span></label></li>' for i in r['ingredients'])
 steps='<ol class="steps">'+''.join(f'<li>{esc(s)}</li>' for s in r['steps'])+'</ol>' if r['steps'] else '<p>Способ приготовления в записи отсутствует.</p>'
 notes='<section class="notes-section"><h2>Записи на полях</h2>'+''.join(f'<p>{esc(s)}</p>' for s in r['notes'])+'</section>' if r['notes'] else ''
 issues='<section class="notes-section clarifications"><h2>Уточнения к источнику</h2>'+''.join(f'<p>{esc(s)}</p>' for s in r['issues'])+'</section>' if r['issues'] else ''
 prev=f'<a href="{url(R[idx-1])}">← {esc(R[idx-1]["title"])}</a>' if idx else '<span></span>'
 next_=f'<a href="{url(R[idx+1])}">{esc(R[idx+1]["title"])} →</a>' if idx+1<len(R) else '<span></span>'
 body=f'''<main id="main" class="book-page"><div class="breadcrumbs"><a href="/recipes/">Книга</a> / <a href="/recipes/?category={esc(r['category'])}">{esc(r['category'])}</a> / {r['number']:02}</div><article><header class="recipe-header"><p class="eyebrow">{esc(r['category'])} · Рецепт {r['number']:02}</p><h1>{esc(r['title'])}</h1>{'<p class="tag">Фрагмент рецепта: часть количеств или действий не записана.</p>' if r['kind']=='fragment' else ''}<p class="yield">{esc('Выход: '+r['yieldText'] if r['yieldText'] else 'Выход в источнике не указан')}</p></header><div class="recipe-actions js-only"><button data-favorite="{r['id']}" data-title="{esc(r['title'])}" aria-pressed="false">В избранное</button><button id="read-mode" aria-pressed="false">Крупный текст</button><button id="print">Печать</button><button id="copy-link">Скопировать ссылку</button></div><div class="recipe-body"><section><h2>Ингредиенты</h2><ul class="ingredients">{ingredients}</ul><p class="eyebrow" style="margin-top:16px">Пары значений — брутто / нетто</p><button id="reset-checks" class="js-only">Снять отметки</button></section><div><section><h2>Приготовление</h2>{steps}</section>{notes}{issues}</div></div>{sources_panel(r['sources'])}<p class="back-link">Источники: {source_links(r['sources'])}</p></article><nav class="page-nav" aria-label="Соседние рецепты">{prev}{next_}</nav></main>'''
 write(f'r/{r["id"]}/index.html',shell(r['title'],body,r['id'],f"{r['title']}: ингредиенты, приготовление, варианты и исходные сканы.",f'r/{r["id"]}/'))
notes=''.join(f'<article class="note" id="{n["id"]}"><h2>{esc(n["title"])}</h2><p>{esc(n["text"])}</p><p class="uncertain">{esc(n["issue"])}</p><p>{source_links(n["sources"])}</p>{sources_panel(n["sources"])}</article>' for n in N)
write('notes/index.html',shell('Кухонные заметки',f'<main id="main" class="book-page"><p class="eyebrow">На оборотах и полях</p><h1 class="page-title">Кухонные заметки</h1><p class="archive-intro">Идеи блюд, варианты, схемы и планы. Незавершённые записи сохранены как конспект, без придуманных пропорций.</p>{notes}</main>',path='notes/'))
archive=[]
for d,count in [(1,24),(2,24),(3,24),(4,22)]:
 archive.append(f'<section class="notes-section" id="pdf-{d}"><h2>Тетрадь {d} · {count} страницы</h2><p><a href="/recipes/originals/scan-{d}.pdf">Скачать исходный PDF {d}</a></p><div class="archive-list">')
 for p in [p for p in P if p['pdf']==d]:
  src=f'/recipes/scans/{d}-{p["page"]:02}.jpg'
  archive.append(f'<article class="archive-card"><a href="{src}" target="_blank" rel="noopener"><img loading="lazy" src="{src}" alt="PDF {d}, страница {p["page"]}"></a><h3>Страница {p["page"]}</h3><p>{esc("; ".join(p["entries"]))}</p><a href="{src}" target="_blank" rel="noopener">Открыть лист</a> · <a href="/recipes/originals/scan-{d}.pdf#page={p["page"]}">В PDF</a></article>')
 archive.append('</div></section>')
write('archive/index.html',shell('Архив сканов','<main id="main" class="book-page"><p class="eyebrow">Каждый лист сохранён</p><h1 class="page-title">Четыре тетради</h1><p class="archive-intro">Все 94 страницы: печатные таблицы, рукописные дополнения, калькуляции и обороты. Превью повёрнуты для чтения. Исходные PDF сохранены без изменений.</p><div class="downloads">'+''.join(f'<a href="#pdf-{i}">Тетрадь {i}</a>' for i in range(1,5))+'</div>'+''.join(archive)+'</main>',path='archive/'))
about='''<main id="main" class="book-page"><p class="eyebrow">Оцифрованная коллекция</p><h1 class="page-title">О книге</h1><p class="archive-intro">73 рецептурные записи из четырёх PDF. Рукописные дополнения, продолжения и повторные версии собраны вместе. 15 групп кухонных заметок сохранены отдельно.</p><div class="downloads"><a download href="/recipes/downloads/recipe-book.docx">Книга Word</a><a download href="/recipes/downloads/recipe-book.md">Текст Markdown</a><a download href="/recipes/data/recipes.json">База рецептов JSON</a></div><section class="note"><h2>Как читать книгу</h2><p>Сначала идут завтраки, супы, основные блюда, салаты, выпечка, хлеб и напитки. Отдельные рукописные рецепты и технологические карты вынесены в свои разделы. Карты расположены по номерам; три варианта пшённой каши из карты № 22 разделены для удобства. Повторяющиеся щи № 7 и № 9 объединены с сохранением различий.</p><p>Пары количеств, например 800/670 г, означают брутто и нетто. Стаканы, ложки и пачки оставлены в единицах оригинала. Неточные количества, противоречия и пропуски вынесены в «Уточнения к источнику». «Фрагмент» означает, что исходная запись неполная.</p></section><section class="note"><h2>Рукописные пометки</h2><p>Разборчивые кулинарные дополнения перенесены в рецепты и заметки. Неразборчивые или обрезанные фразы отмечены явно. Схемы, бытовые записи и все расчёты доступны в архиве листов. Ни пропорции, ни недостающие этапы не дополнены рецептами из интернета.</p><p>Исторические цены и калькуляции не являются текущими. Они сохранены на оригиналах; часть читаемых итогов перенесена в примечания. Полной проверенной текстовой расшифровки всех ценовых пометок пока нет. Противоречивые выходы и числа сохранены без пересчёта.</p></section><section class="note"><h2>Пользование на кухне</h2><p>Отмечайте ингредиенты по мере подготовки, добавляйте блюда в избранное, включайте крупный текст и печатайте отдельный рецепт. Отметки и избранное сохраняются в этом браузере на этом устройстве; между устройствами они не синхронизируются.</p><p>Под каждым рецептом можно раскрыть сканы и открыть их крупно. Без JavaScript страницы и рецепты остаются доступны; поиск и сохранение отметок требуют JavaScript.</p></section><section class="note"><h2>Исходные файлы</h2><p>PDF 1 — «Отсканированный документ.pdf», 24 страницы. PDF 2 — «Отсканированный документ 2.pdf», 24 страницы. PDF 3 — «Отсканированный документ 3.pdf», 24 страницы. PDF 4 — «Отсканированный документ 4.pdf», 22 страницы.</p><p><a href="/recipes/archive/">Все исходные страницы</a> · <a href="/recipes/data/source-manifest.json">Контрольные суммы оригиналов</a></p></section></main>'''
write('about/index.html',shell('О книге',about,path='about/'))
write('404.html',shell('Страница не найдена','<main id="main" class="book-page"><p class="eyebrow">404</p><h1 class="page-title">Этот лист не найден</h1><p><a href="/recipes/">Вернуться к рецептам</a></p></main>'))
write('favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="5" fill="#ffffff"/><path d="M9 9h9c3 0 4 2 4 3v20c-1-2-3-3-5-3H9zm22 0h-5c-2 0-4 2-4 3v20c1-2 3-3 5-3h4z" fill="none" stroke="#c91f29" stroke-width="2"/></svg>')
print(f'Built {len(R)} recipe pages, notes and archive')
